  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Safinamide absolute oral bioavailability was 95% (83.9–119.3%) after a 50 mg IR tablet in fasted subjects vs IV, strongly supporting F ≥ 20%."
    },
    {
      "card_ids": ["C49"],
      "claim": "Tolfenamic acid absolute oral bioavailability averaged 60% vs IV in healthy volunteers across oral doses, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C43"],
      "claim": "Isradipine absolute oral bioavailability was 16% vs IV in healthy subjects, below the 20% threshold and providing the main contradictory evidence."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C43"],
  "decision_summary": "Most transferred evidence (8 of 10 molecules) shows absolute oral bioavailability at or above roughly 26–95%, well above the 20% threshold; the only consistently low molecule is isradipine at 16% in healthy subjects. Direct absolute bioavailability vs IV records dominate, so high is predicted.",
  "evidence_gaps": [
    "The main contradictory evidence is limited to isradipine, with F = 16% in healthy subjects; no other low-F absolute records were supplied.",
    "Some records report systemic availability rather than absolute F, but direct absolute bioavailability records provide the primary basis."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C28", "C49"],
  "revision_action": "initial",
  "supportive_card_ids": ["C28", "C49"]
}

